  Object.assign(S.en, {"lqTitle":"Liquidity map","lqBtn":"Liquidity","lqSec":"{n}s","lqMin":"{n} min","lqOff":"Off. Tick the box above to start reading the order books.","lqNoSym":"The liquidity map works on coins traded against USDT on Binance, Bybit or OKX. {s} is not one of them.","lqV_bnf":"Binance futures","lqV_bns":"Binance spot","lqV_byf":"Bybit futures","lqV_okx":"OKX spot","lqWait":"waiting for the first answer","lqVOk":"book from {lo} to {hi}, read {t} ago","lqVBad":"not reachable from here right now","lqL_bnf":"Binance liquidations","lqL_byf":"Bybit liquidations","lqLiveOk":"live","lqNow":"{n} books joined. Every one of them covers {lo} to {hi}, in steps of {step}. {k} readings kept since you switched it on ({since}).","lqWPrice":"Price range","lqWDist":"From mid","lqWSize":"Size","lqWHeld":"Held","lqWTop":"Biggest share","lqLiqSum":"{n} liquidations seen in {since}: longs closed {l}, shorts closed {s}.","lqLong":"Long liquidated","lqShort":"Short liquidated","lqWhyT":"What this map shows, and what it does not","lqWhy1":"Only data the exchanges publish: their order books, read every 10 seconds, and their liquidation feeds. Nothing is estimated, and no \"liquidation levels\" are guessed from leverage.","lqWhy2":"Green is waiting buy orders, red is waiting sell orders. The bars at the right edge are the books now; the heat map behind the candles is each reading kept while this page is open. Nothing older can be shown, because no free source keeps old order books.","lqWhy3":"An order can be pulled at any moment, so a wall shows what was there, not a promise. Each book only reaches part of the way from the price: past the range every chosen book covers, totals would be missing orders, so they are faded and left out of the list. Binance sends at most one liquidation per coin per second, so its count is a floor; Bybit sends all of them.","lqShow":"Show on the chart","lqBooks":"Order books","lqLayers":"Layers","lqLay_heat":"Heat map over time","lqLay_prof":"Book now (right edge)","lqLay_liq":"Liquidations","lqStep":"Price step","lqWallsT":"Biggest walls now","lqLiqT":"Liquidations while open","lqSrcT":"Sources and how fresh they are","lqWallNote":"\"Held\" is how long the wall has kept at least half of its size in the readings kept here."});
  Object.assign(S.fa, {"lqTitle":"نقشه‌ی نقدینگی","lqBtn":"نقدینگی","lqSec":"{n} ثانیه","lqMin":"{n} دقیقه","lqOff":"خاموش است. تیک بالا را بزن تا خواندن دفتر سفارش‌ها شروع شود.","lqNoSym":"نقشه‌ی نقدینگی روی کوین‌هایی کار می‌کند که در بایننس، بای‌بیت یا او‌کی‌ایکس با تتر معامله می‌شوند. {s} از آن‌ها نیست.","lqV_bnf":"فیوچرز بایننس","lqV_bns":"اسپات بایننس","lqV_byf":"فیوچرز بای‌بیت","lqV_okx":"اسپات او‌کی‌ایکس","lqWait":"منتظر اولین جواب","lqVOk":"دفتر از {lo} تا {hi}، {t} پیش خوانده شد","lqVBad":"الان از اینجا در دسترس نیست","lqL_bnf":"لیکوئید‌های بایننس","lqL_byf":"لیکوئید‌های بای‌بیت","lqLiveOk":"زنده","lqNow":"{n} دفتر سفارش با هم جمع شد. همه‌شان از {lo} تا {hi} را پوشش می‌دهند، با پله‌ی {step}. {k} خوانش از وقتی روشنش کردی ({since}) نگه داشته شده.","lqWPrice":"بازه‌ی قیمت","lqWDist":"فاصله تا وسط","lqWSize":"حجم","lqWHeld":"دوام","lqWTop":"بیشترین سهم","lqLiqSum":"در {since}، {n} لیکوئید دیده شد: لانگ‌های بسته‌شده {l}، شورت‌های بسته‌شده {s}.","lqLong":"لانگ لیکوئید شد","lqShort":"شورت لیکوئید شد","lqWhyT":"این نقشه چه نشان می‌دهد و چه نشان نمی‌دهد","lqWhy1":"فقط داده‌ای که خود صرافی‌ها منتشر می‌کنند: دفتر سفارش‌شان که هر ۱۰ ثانیه خوانده می‌شود و فید لیکوئیدشان. هیچ چیزی تخمینی نیست و هیچ «سطح لیکوئیدی» از روی اهرم حدس زده نمی‌شود.","lqWhy2":"سبز سفارش‌های خرید منتظر است و قرمز سفارش‌های فروش منتظر. میله‌های لبه‌ی راست، دفترها در همین لحظه‌اند؛ نقشه‌ی حرارتی پشت کندل‌ها هر خوانشی است که از وقتی این صفحه باز است نگه داشته شده. قدیمی‌تر از آن نشان داده نمی‌شود، چون هیچ منبع رایگانی دفتر سفارش‌های گذشته را نگه نمی‌دارد.","lqWhy3":"هر سفارش هر لحظه می‌تواند برداشته شود، پس دیوار یعنی چیزی که آنجا بود، نه قول. هر دفتر فقط تا بخشی از فاصله‌ی قیمت می‌رسد: بیرون از بازه‌ای که همه‌ی دفترهای انتخاب‌شده پوشش می‌دهند جمع‌ها ناقص‌اند، پس کم‌رنگ می‌شوند و در فهرست نمی‌آیند. بایننس برای هر کوین حداکثر یک لیکوئید در ثانیه می‌فرستد، پس شمارش آن حداقل است؛ بای‌بیت همه را می‌فرستد.","lqShow":"نمایش روی چارت","lqBooks":"دفتر سفارش‌ها","lqLayers":"لایه‌ها","lqLay_heat":"نقشه‌ی حرارتی در طول زمان","lqLay_prof":"دفتر همین الان (لبه‌ی راست)","lqLay_liq":"لیکوئیدها","lqStep":"پله‌ی قیمت","lqWallsT":"بزرگ‌ترین دیوارهای الان","lqLiqT":"لیکوئیدها از وقتی باز است","lqSrcT":"منبع‌ها و تازگی‌شان","lqWallNote":"«دوام» یعنی دیوار در خوانش‌هایی که اینجا نگه داشته شده چه مدت دست‌کم نصف حجم فعلی‌اش را داشته است."});
  Object.assign(S.ckb, {"lqTitle":"نەخشەی لیکوئیدیتی","lqBtn":"لیکوئیدیتی","lqSec":"{n} چرکە","lqMin":"{n} خولەک","lqOff":"کوژاوەتەوە. تیکی سەرەوە هەڵبژێرە بۆ ئەوەی خوێندنەوەی دفتری داواکارییەکان دەست پێ بکات.","lqNoSym":"نەخشەی لیکوئیدیتی تەنها لەسەر ئەو کۆینانە کار دەکات کە بە USDT لە Binance، Bybit یان OKX مامەڵەیان پێوە دەکرێت. {s} یەکێک لەوان نییە.","lqV_bnf":"فیوچەرزی Binance","lqV_bns":"سپۆتی Binance","lqV_byf":"فیوچەرزی Bybit","lqV_okx":"سپۆتی OKX","lqWait":"چاوەڕێی یەکەم وەڵام","lqVOk":"دفتر لە {lo} تا {hi}، {t} لەمەوبەر خوێندراوەتەوە","lqVBad":"ئێستا لێرەوە بەردەست نییە","lqL_bnf":"لیکوئیدەکانی Binance","lqL_byf":"لیکوئیدەکانی Bybit","lqLiveOk":"ڕاستەوخۆ","lqNow":"{n} دفتری داواکاری کۆ بوونەتەوە. هەمووی لە {lo} تا {hi} دەگرنەوە، بە هەنگاوی {step}. {k} خوێندنەوە هەڵگیراون لەو کاتەوەی کردتە کارا ({since}).","lqWPrice":"بازنەی نرخ","lqWDist":"دووری لە ناوەند","lqWSize":"قەبارە","lqWHeld":"مانەوە","lqWTop":"زۆرترین بەش","lqLiqSum":"لە {since}دا {n} لیکوئید بینرا: لۆنگە داخراوەکان {l}، شۆرتە داخراوەکان {s}.","lqLong":"لۆنگ لیکوئید کرا","lqShort":"شۆرت لیکوئید کرا","lqWhyT":"ئەم نەخشەیە چی نیشان دەدات، و چی نیشان نادات","lqWhy1":"تەنها ئەو داتایەی کە خودی بۆرسەکان بڵاوی دەکەنەوە: دفتری داواکارییەکانیان کە هەموو ١٠ چرکە جارێک دەخوێندرێنەوە، و فیدی لیکوئیدەکانیان. هیچ شتێک خەملاندن نییە و هیچ «ئاستی لیکوئید» لە ڕێگەی لیڤەرێجەوە نەخەمڵێندراوە.","lqWhy2":"سەوز داواکارییە چاوەڕوانکراوەکانی کڕینە، سوور داواکارییە چاوەڕوانکراوەکانی فرۆشتن. ستوونەکانی لێواری ڕاست دفتری ئێستان؛ نەخشەی گەرمی پشت کاندڵەکان هەر خوێندنەوەیەکە کە لەو کاتەوە هەڵگیراوە کە ئەم لاپەڕەیە کراوەیە. هیچ شتێکی کۆنتر پیشان نادرێت، چونکە هیچ سەرچاوەیەکی بەخۆڕایی دفتری داواکاری کۆنەکان ناپارێزێت.","lqWhy3":"هەر داواکارییەک لە هەر کاتێکدا دەتوانرێت لابرێت، بۆیە دیوار تەنها ئەوە پیشان دەدات کە لەوێ بووە، نەک بەڵێن. هەر دفترێک تەنها بەشێک لە دووری نرخەکە دەگاتە. لەو بازنەیەی هەموو دفترە هەڵبژێردراوەکان دەیگرنەوە دەرەوە، کۆەکان تەواو نین، بۆیە کاڵ دەبنەوە و لە لیستەکەدا نایەن. Binance بۆ هەر کۆینێک زۆرترین یەک لیکوئید لە چرکەیەکدا دەنێرێت، بۆیە ژمارەکەی کەمترین ژمارەیە؛ Bybit هەمووی دەنێرێت.","lqShow":"پیشاندان لەسەر چارت","lqBooks":"دفتری داواکارییەکان","lqLayers":"قاتەکان","lqLay_heat":"نەخشەی گەرمی بەپێی کات","lqLay_prof":"دفتری ئێستا (لێواری ڕاست)","lqLay_liq":"لیکوئیدەکان","lqStep":"هەنگاوی نرخ","lqWallsT":"گەورەترین دیوارەکانی ئێستا","lqLiqT":"لیکوئیدەکان لەو کاتەوەی کراوەتەوە","lqSrcT":"سەرچاوەکان و تازەیی ئەوان","lqWallNote":"«مانەوە» ماوەی ئەوەیە کە دیوارەکە بۆ ماوەیەک کەمتر نەبووە لە نیوەی قەبارەکەی لە خوێندنەوە هەڵگیراوەکانی ئەم لاپەڕەیەدا."});
  Object.assign(S.ar, {"lqTitle":"خريطة السيولة","lqBtn":"السيولة","lqSec":"{n} ث","lqMin":"{n} د","lqOff":"متوقفة. ضع علامة في المربع أعلاه لبدء قراءة دفاتر الأوامر.","lqNoSym":"تعمل خريطة السيولة على العملات المتداولة مقابل USDT في Binance أو Bybit أو OKX. {s} ليست من بينها.","lqV_bnf":"عقود Binance الآجلة","lqV_bns":"سوق Binance الفوري","lqV_byf":"عقود Bybit الآجلة","lqV_okx":"سوق OKX الفوري","lqWait":"في انتظار أول رد","lqVOk":"دفتر من {lo} إلى {hi}، قُرئ قبل {t}","lqVBad":"غير متاح من هنا حالياً","lqL_bnf":"تصفيات Binance","lqL_byf":"تصفيات Bybit","lqLiveOk":"مباشر","lqNow":"تم جمع {n} دفتر أوامر. يغطي كل منها النطاق من {lo} إلى {hi}، بخطوات قدرها {step}. تم حفظ {k} قراءة منذ تشغيلها ({since}).","lqWPrice":"نطاق السعر","lqWDist":"المسافة من المنتصف","lqWSize":"الحجم","lqWHeld":"المدة","lqWTop":"أكبر حصة","lqLiqSum":"تم رصد {n} تصفية خلال {since}: إغلاق لونغ {l}، إغلاق شورت {s}.","lqLong":"تصفية لونغ","lqShort":"تصفية شورت","lqWhyT":"ماذا تعرض هذه الخريطة، وماذا لا تعرض","lqWhy1":"بيانات تنشرها المنصات نفسها فقط: دفاتر أوامرها التي تُقرأ كل 10 ثوانٍ، وتغذية التصفيات لديها. لا يُقدَّر شيء، ولا تُخمَّن «مستويات تصفية» من الرافعة المالية.","lqWhy2":"الأخضر أوامر شراء معلقة، والأحمر أوامر بيع معلقة. الأعمدة عند الحافة اليمنى هي الدفاتر الآن، وخريطة الحرارة خلف الشموع هي كل قراءة محفوظة منذ فتح هذه الصفحة. لا يمكن عرض ما هو أقدم، لأن لا مصدر مجانياً يحتفظ بدفاتر أوامر سابقة.","lqWhy3":"يمكن سحب أي أمر في أي لحظة، فالجدار يُظهر ما كان موجوداً لا وعداً. كل دفتر يصل إلى جزء فقط من المسافة عن السعر: خارج النطاق الذي تغطيه كل الدفاتر المختارة تكون المجاميع ناقصة، لذلك تُخفَّف وتُستبعد من القائمة. ترسل Binance تصفية واحدة لكل عملة في الثانية كحد أقصى، لذا فعدّها حد أدنى؛ أما Bybit فترسل كلها.","lqShow":"عرض على الرسم البياني","lqBooks":"دفاتر الأوامر","lqLayers":"الطبقات","lqLay_heat":"خريطة حرارة عبر الزمن","lqLay_prof":"الدفتر الآن (الحافة اليمنى)","lqLay_liq":"التصفيات","lqStep":"خطوة السعر","lqWallsT":"أكبر الجدران الآن","lqLiqT":"التصفيات منذ فتح الصفحة","lqSrcT":"المصادر ومدى حداثتها","lqWallNote":"«المدة» هي المدة التي حافظ فيها الجدار على نصف حجمه على الأقل في القراءات المحفوظة هنا."});
