  Object.assign(S.ar, {"odDragAt": "{l} عند {p} ({d}% من آخر سعر)", "odDragHint": "اسحب الخط المعلَّم بـ ↕ لتحريكه. تُعاد حسابات الخطة فوراً أثناء السحب.", "odPick_e": "انقر على الرسم حيث تريد الدخول الجديد. Esc للإلغاء.", "odPick_s": "انقر على الرسم حيث تريد وقف الخسارة. Esc للإلغاء.", "odPick_x": "انقر على الرسم حيث تريد الهدف الجديد. Esc للإلغاء.", "odHudE": "دخول", "odHudS": "وقف الخسارة", "odHudX": "هدف", "odHudOpen": "فتح ODM", "odHudUndo": "تراجع عن آخر تغيير", "odUndone": "تم التراجع عن آخر تغيير.", "odShown": "تم رسم {n} مستوى. اسحب خطاً لتغيير الخطة، أو انقر بالزر الأيمن على الرسم لإزالتها.", "odClearedBoth": "أُزيل {n} مستوى و{m} تنبيه ODM.", "odClearedAl": "أُزيل {m} تنبيه ODM.", "ctxOpenOdm": "فتح ODM", "ctxOdmHide": "إزالة مستويات ODM وتنبيهاتها", "ctxAlDel": "حذف هذا التنبيه", "ctxAlGone": "حُذف {n} تنبيه.", "ctxRemoved": "أُزيل {x}.", "ctxRemoved1": "إزالة {x}", "ctxIndsGone": "أُزيل {n} مؤشر.", "ctxRemoveH": "إزالة من الرسم", "ctxBack": "رجوع", "ctxIndOne": "مؤشر واحد…", "ctxAllInds": "كل المؤشرات ({n})", "ctxDrwOne": "رسم واحد…", "ctxDrwH": "الرسوم، الأحدث أولاً", "ctxAllDraw": "كل الرسوم ({n})", "ctxDrawGone": "أُزيل {n} رسم.", "ctxOdmLv": "مستويات ODM وتنبيهاتها", "ctxAlAll": "كل تنبيهات هذه العملة", "ctxClearAll": "مسح الرسم بالكامل", "ctxClearQ": "إزالة كل الرسوم والمؤشرات، ومستويات ODM مع تنبيهاتها، من {s}؟ تبقى التنبيهات الأخرى. يمكنك التراجع.", "ctxCleared": "تم مسح الرسم.", "ctxNothing": "لا شيء لإزالته"});
  Object.assign(S.en, {"odGuide": "Guide me, step by step", "odTourOffer": "New to ODM? A one-minute tour shows what each part does.", "odTourGo": "Start the tour", "odTourNo": "Not now", "odTourN": "{i} of {n}", "odTourBack": "Back", "odTourNext": "Next", "odTourDone": "Done", "odTourSkip": "Close the tour", "odTr_acc_t": "Your account", "odTr_acc_b": "Set your balance, the risk per trade in percent, the leverage and the fees. The risk is the most you lose if every entry fills and the stop is hit.", "odTr_ent_t": "Where you get in", "odTr_ent_b": "Up to 10 limit prices, each with its share. Build a ladder in one tap or type your own prices. The shares must add up to 100%.", "odTr_stop_t": "Where you are wrong", "odTr_stop_b": "The stop sits beyond the deepest entry. Set it by price, by percent, or as a multiple of ATR so it follows how wild the market is.", "odTr_exit_t": "Where you take profit", "odTr_exit_b": "Up to 8 steps, each at a price, a percent from the average entry, or a multiple of R, your risk per coin.", "odTr_trail_t": "What is left", "odTr_trail_b": "The share no exit closes can ride a trailing stop, and the stop can move to break-even once an exit fills.", "odTr_top_t": "The plan at a glance", "odTr_top_b": "Risk, average entry, stop, R and the best result, worked out again as you type.", "odTr_res_t": "The full picture", "odTr_res_b": "Size, margin, the liquidation estimate and the result of every way the trade can end, fees included.", "odTr_loss_t": "The loss at each step", "odTr_loss_b": "If the stop is hit after only some entries fill, you lose less. The bar shows how much of your full risk that is.", "odTr_help_t": "Stuck? Tap an icon", "odTr_help_b": "Every section, field and result has its own icon. It explains the part, gives an example with your numbers, and has a box for your question.", "odTr_act_t": "Put it to work", "odTr_act_b": "Show the plan on the chart and drag its lines, test it on past candles, add an alert for each level, or save it to the risk board. Nothing here places an order."});
  Object.assign(S.fa, {"odGuide": "راهنمای قدم‌به‌قدم", "odTourOffer": "اولین بار است ODM را باز می‌کنی؟ یک راهنمای یک‌دقیقه‌ای نشان می‌دهد هر بخش چه کار می‌کند.", "odTourGo": "شروع راهنما", "odTourNo": "الان نه", "odTourN": "{i} از {n}", "odTourBack": "قبلی", "odTourNext": "بعدی", "odTourDone": "تمام", "odTourSkip": "بستن راهنما", "odTr_acc_t": "حساب تو", "odTr_acc_b": "موجودی، درصد ریسک هر معامله، اهرم و کارمزد را اینجا بنویس. ریسک یعنی بیشترین مبلغی که از دست می‌دهی اگر همه‌ی ورودها پر شوند و حد ضرر بخورد.", "odTr_ent_t": "کجا وارد می‌شوی", "odTr_ent_b": "تا ۱۰ قیمت لیمیت، هر کدام با سهم خودش. با یک کلیک پله بساز یا قیمت‌های خودت را بنویس. جمع سهم‌ها باید ۱۰۰٪ شود.", "odTr_stop_t": "کجا اشتباه کرده‌ای", "odTr_stop_b": "حد ضرر آن‌سوی عمیق‌ترین ورود است. با قیمت، با درصد یا با ضریبی از ATR تعیینش کن تا با نوسان بازار جور باشد.", "odTr_exit_t": "کجا سود برمی‌داری", "odTr_exit_b": "تا ۸ پله، هر کدام در یک قیمت، درصدی از میانگین ورود یا ضریبی از R، یعنی ریسک تو برای هر واحد.", "odTr_trail_t": "باقی‌مانده", "odTr_trail_b": "سهمی که هیچ خروجی نمی‌بندد می‌تواند با حد ضرر متحرک جلو برود، و بعد از پر شدن یک خروج حد ضرر به سربه‌سر برود.", "odTr_top_t": "برنامه در یک نگاه", "odTr_top_b": "ریسک، میانگین ورود، حد ضرر، R و بهترین نتیجه، همزمان با تایپ تو دوباره حساب می‌شوند.", "odTr_res_t": "تصویر کامل", "odTr_res_b": "حجم، مارجین، تخمین قیمت لیکوئید و نتیجه‌ی همه‌ی حالت‌های پایان معامله، با کارمزد.", "odTr_loss_t": "زیان در هر پله", "odTr_loss_b": "اگر فقط بعضی ورودها پر شوند و حد ضرر بخورد، کمتر از دست می‌دهی. نوار نشان می‌دهد این چند درصد از کل ریسک توست.", "odTr_help_t": "جایی را نفهمیدی؟ روی آیکون بزن", "odTr_help_b": "هر بخش، هر خانه و هر نتیجه آیکون خودش را دارد. توضیح می‌دهد، با عددهای خودت مثال می‌زند و جایی برای پرسیدن سؤالت دارد.", "odTr_act_t": "حالا به کارش بگیر", "odTr_act_b": "برنامه را روی نمودار ببین و خط‌هایش را بکش، روی کندل‌های گذشته امتحانش کن، برای هر سطح هشدار بگذار یا در تابلوی ریسک ذخیره‌اش کن. اینجا هیچ سفارشی ثبت نمی‌شود."});
  Object.assign(S.ckb, {"odGuide": "ڕێنمایی هەنگاو بە هەنگاو", "odTourOffer": "یەکەم جارە ODM دەکەیتەوە؟ ڕێنماییەکی یەک خولەکی پیشانت دەدات هەر بەشێک چی دەکات.", "odTourGo": "دەستپێکردنی ڕێنمایی", "odTourNo": "ئێستا نا", "odTourN": "{i} لە {n}", "odTourBack": "پێشوو", "odTourNext": "دواتر", "odTourDone": "تەواو", "odTourSkip": "داخستنی ڕێنمایی", "odTr_acc_t": "هەژمارەکەت", "odTr_acc_b": "باڵانس، ڕێژەی مەترسی هەر مامەڵەیەک، لیڤەریج و کرێکان لێرە بنووسە. مەترسی واتە زۆرترین بڕێک کە لە دەستی دەدەیت ئەگەر هەموو چوونەژوورەوەکان پڕ بن و حەدی زیان بدات.", "odTr_ent_t": "لە کوێ دەچیتە ژوورەوە", "odTr_ent_b": "تا 10 نرخی سنووردار، هەریەکەیان بە بەشی خۆی. بە یەک کلیک هەنگاو دروست بکە یان نرخەکانی خۆت بنووسە. کۆی بەشەکان دەبێت 100% بێت.", "odTr_stop_t": "لە کوێ هەڵەت کردووە", "odTr_stop_b": "حەدی زیان لە پشت قووڵترین چوونەژوورەوەیە. بە نرخ، بە ڕێژە یان بە ژمارەیەکی ATR دیاری بکە بۆ ئەوەی لەگەڵ جووڵەی بازار بگونجێت.", "odTr_exit_t": "لە کوێ قازانج وەردەگریت", "odTr_exit_b": "تا 8 هەنگاو، هەریەکەیان لە نرخێک، ڕێژەیەک لە ناوەندی چوونەژوورەوە، یان ژمارەیەکی R، واتە مەترسیی تۆ بۆ هەر یەکەیەک.", "odTr_trail_t": "ئەوەی دەمێنێتەوە", "odTr_trail_b": "ئەو بەشەی هیچ دەرچوونێک دایناخات دەتوانێت بە حەدی زیانی جوڵاو بەردەوام بێت، و دوای پڕبوونی دەرچوونێک حەدی زیان بچێتە خاڵی هاوسەنگی.", "odTr_top_t": "پلانەکە بە یەک سەیرکردن", "odTr_top_b": "مەترسی، ناوەندی چوونەژوورەوە، حەدی زیان، R و باشترین ئەنجام، لەگەڵ نووسینەکەت دووبارە حیساب دەکرێنەوە.", "odTr_res_t": "وێنەی تەواو", "odTr_res_b": "قەبارە، مارجن، مەزەندەی لیکوئید و ئەنجامی هەموو ڕێگاکانی کۆتایی مامەڵەکە، لەگەڵ کرێ.", "odTr_loss_t": "زیان لە هەر هەنگاوێک", "odTr_loss_b": "ئەگەر تەنها هەندێک چوونەژوورەوە پڕ بن و حەدی زیان بدات، کەمتر لە دەست دەدەیت. هێڵەکە نیشان دەدات ئەمە چەند لە سەدی مەترسیی تەواوتە.", "odTr_help_t": "شتێکت تێنەگەیشت؟ ئایکۆنێک دابگرە", "odTr_help_b": "هەر بەش و خانە و ئەنجامێک ئایکۆنی خۆی هەیە. ڕوونی دەکاتەوە، بە ژمارەکانی خۆت نموونە دەهێنێتەوە و شوێنێکی هەیە بۆ پرسیارەکەت.", "odTr_act_t": "ئێستا بەکاری بهێنە", "odTr_act_b": "پلانەکە لەسەر چارت ببینە و هێڵەکانی ڕابکێشە، لەسەر کەنجیلە ڕابردووەکان تاقی بکەرەوە، بۆ هەر ئاستێک ئاگادارکردنەوە دابنێ یان لە تابلۆی مەترسی پاشەکەوتی بکە. هیچ فەرمانێک لێرە دانانرێت."});
